class VoicePitch extends AudioWorkletProcessor{static get parameterDescriptors(){return[{name:'ratio',defaultValue:1,minValue:.5,maxValue:2}];}constructor(){super();this.ring=new Float32Array(16384);this.pos=0;this.phase=0;}process(inputs,outputs,params){const input=inputs[0]?.[0],out=outputs[0];if(!input)return true;for(let i=0;i<input.length;i++){this.ring[this.pos]=input[i];const ratio=params.ratio.length>1?params.ratio[i]:params.ratio[0];let value=input[i];if(Math.abs(ratio-1)>.01){this.phase=(this.phase+(1-ratio)/2048+1)%1;value=0;for(const shift of [0,.5]){const p=(this.phase+shift)%1,d=128+p*2048,read=(this.pos-d+16384)%16384,n=Math.floor(read),f=read-n,g=.5-.5*Math.cos(p*Math.PI*2);value+=(this.ring[n]*(1-f)+this.ring[(n+1)%16384]*f)*g;}}for(const channel of out)channel[i]=value;this.pos=(this.pos+1)%16384;}return true;}}registerProcessor('local-voice-pitch',VoicePitch);
